/**
 * Figma snapshot → StyleX token files.
 *
 *   pnpm gen:tokens
 *
 * Source of truth: figma/_tokens/foundations.json (pulled from the Figma
 * variable collections). Never edit the generated files by hand — refresh the
 * snapshot from Figma and re-run.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

interface Foundations {
  schemes: Record<string, Record<string, string>>;
  fontTheme: { font: Record<'Brand' | 'Plain', string>; weight: Record<string, string> };
  typescale: Record<
    string,
    { font: 'Brand' | 'Plain'; size: number; lineHeight: number; tracking: number; weight: string; weightEmphasized: string }
  >;
  shape: Record<string, number>;
  elevation: Record<string, Array<{ x: number; y: number; blur: number; spread: number; alpha: number }>>;
}

const root = new URL('../', import.meta.url);
const snapshotPath = fileURLToPath(new URL('figma/_tokens/foundations.json', root));
const tokensDir = fileURLToPath(new URL('packages/m3/src/tokens/', root));
const HEADER = '// GENERATED by scripts/gen-tokens.ts from figma/_tokens/foundations.json — do not edit.\n';

const camel = (s: string) =>
  s
    .split(/[\s-]+/)
    .map((w, i) => (i === 0 ? w.toLowerCase() : w[0]!.toUpperCase() + w.slice(1).toLowerCase()))
    .join('');

const WEIGHT: Record<string, number> = { Regular: 400, Medium: 500, SemiBold: 600, Bold: 700 };

/** Figma → CSS drop-shadow calibration (see `shadow` below). */
export const FIGMA_BLUR_TO_CSS = 0.92;
export const FIGMA_SHADOW_ALPHA = 1.03;
const round2 = (n: number) => Math.round(n * 100) / 100;
const round4 = (n: number) => Math.round(n * 10000) / 10000;

function lightDark(light: string, dark: string) {
  return light === dark ? `'${light}'` : `'light-dark(${light}, ${dark})'`;
}

export function render(f: Foundations): Record<string, string> {
  const roles = Object.entries(f.schemes);
  const colorEntries = (lightMode: string, darkMode: string) =>
    roles.map(([name, m]) => `  ${camel(name)}: ${lightDark(m[lightMode]!, m[darkMode]!)},`).join('\n');

  const color = `${HEADER}import * as stylex from '@stylexjs/stylex';

/**
 * md.sys.color.* — Figma "M3" collection, Light / Dark modes.
 * Resolved with CSS light-dark(): set \`color-scheme\` on any subtree to flip it
 * (M3Provider does this). Contrast levels live in color-themes.ts.
 */
export const color = stylex.defineVars({
${colorEntries('Light', 'Dark')}
});
`;

  const colorThemes = `${HEADER}import * as stylex from '@stylexjs/stylex';
import { color } from './color.stylex';

/** Figma "Light/Dark Medium Contrast" modes. */
export const mediumContrastTheme = stylex.createTheme(color, {
${colorEntries('Light Medium Contrast', 'Dark Medium Contrast')}
});

/** Figma "Light/Dark High Contrast" modes. */
export const highContrastTheme = stylex.createTheme(color, {
${colorEntries('Light High Contrast', 'Dark High Contrast')}
});
`;

  const w = f.fontTheme.weight;
  const typeface = `${HEADER}import * as stylex from '@stylexjs/stylex';

/**
 * md.ref.typeface.* — Figma "Font theme" collection (Baseline mode).
 * Swap these to rebrand. Fonts are loaded by the app, not the library.
 */
export const typeface = stylex.defineVars({
  brand: '"${f.fontTheme.font.Brand}", system-ui, sans-serif',
  plain: '"${f.fontTheme.font.Plain}", system-ui, sans-serif',
  weightRegular: '${WEIGHT[w.Regular!]}',
  weightMedium: '${WEIGHT[w.Medium!]}',
  /** Figma "Static/Weight/Bold" — resolves to the ${w.Bold} face. */
  weightBold: '${WEIGHT[w.Bold!]}',
});
`;

  const weightVar = (name: string) => `typeface.weight${name}`;
  const typeRows: string[] = [];
  for (const emphasized of [false, true]) {
    for (const [name, t] of Object.entries(f.typescale)) {
      const key = camel(name) + (emphasized ? 'Emphasized' : '');
      typeRows.push(
        `  ${key}: { fontFamily: typeface.${t.font.toLowerCase()}, fontWeight: ${weightVar(
          emphasized ? t.weightEmphasized : t.weight,
        )}, fontSize: '${t.size}px', lineHeight: '${t.lineHeight}px', letterSpacing: '${t.tracking}px', [typeMetrics.tracking]: '${t.tracking}px' },`,
      );
    }
  }
  const typescale = `${HEADER}import * as stylex from '@stylexjs/stylex';
import { typeface } from './typeface.stylex';
import { typeMetrics } from './typeMetrics.stylex';

/**
 * md.sys.typescale.* — Figma "Typescale" collection + M3 text styles
 * (baseline and Expressive emphasized). px values, no leading trim.
 *
 * Usage: stylex.props(typescale.labelLarge, ...)
 */
export const typescale = stylex.create({
${typeRows.join('\n')}
});

export type TypescaleRole = keyof typeof typescale;
`;

  const shape = `${HEADER}import * as stylex from '@stylexjs/stylex';

/** md.sys.shape.corner.* — Figma "Shape" collection. */
export const shape = stylex.defineVars({
${Object.entries(f.shape)
  .map(([name, v]) => `  ${camel(`corner ${name}`)}: '${v}px',`)
  .join('\n')}
});
`;

  // Chrome spreads a given blur value wider than Figma does. Fitted against the kit's elevation
  // specimens (scripts in tests/visual/README.md): CSS blur = Figma blur × 0.92, alpha × 1.03 cut
  // the per-level RMS error from 1.3–2.7 to ≤ 1.0 (worst pixel 9 → 5 levels).
  const shadow = (s: Foundations['elevation'][string][number]) =>
    `${s.x}px ${s.y}px ${round2(s.blur * FIGMA_BLUR_TO_CSS)}px ${s.spread}px rgb(0 0 0 / ${round4(s.alpha * FIGMA_SHADOW_ALPHA)})`;
  const elevation = `${HEADER}import * as stylex from '@stylexjs/stylex';

/**
 * md.sys.elevation.level* — Figma "M3/Elevation" effect styles (identical in light and dark),
 * converted to Figma-equivalent CSS (blur × ${FIGMA_BLUR_TO_CSS}, alpha × ${FIGMA_SHADOW_ALPHA}).
 */
export const elevation = stylex.defineVars({
  level0: 'none',
${Object.entries(f.elevation)
  .map(([level, shadows]) => `  level${level}: '${shadows.map(shadow).join(', ')}',`)
  .join('\n')}
  /*
   * Figma ignores shadow spread on frames that don't clip their content; kit variants built that
   * way (e.g. the Focused card) render these.
   */
${Object.entries(f.elevation)
  .map(([level, shadows]) => `  level${level}NoSpread: '${shadows.map((x) => shadow({ ...x, spread: 0 })).join(', ')}',`)
  .join('\n')}
});
`;

  return {
    'color.stylex.ts': color,
    'color-themes.ts': colorThemes,
    'typeface.stylex.ts': typeface,
    'typescale.ts': typescale,
    'shape.stylex.ts': shape,
    'elevation.stylex.ts': elevation,
  };
}

export function loadSnapshot(): Foundations {
  return JSON.parse(readFileSync(snapshotPath, 'utf8')) as Foundations;
}

export { tokensDir };

if (import.meta.url === `file://${process.argv[1]}`) {
  for (const [file, content] of Object.entries(render(loadSnapshot()))) {
    writeFileSync(tokensDir + file, content);
  }
  console.log('tokens written to', tokensDir);
}
